const body = $input.first().json.body ?? {};
const type = body.event_type;
const id = typeof body.event_id === 'string' ? body.event_id.trim() : '';
const invalid = message => [{json:{http_status:400, response:{ok:false,error:message}, manual_review:false}}];
if (!id || !['prediction','summary_report','connectivity_test'].includes(type)) return invalid('Missing or unsupported event ID/type');
if (type === 'connectivity_test') return [{json:{http_status:200,manual_review:false,response:{ok:true,event_id:id,event_type:type,route:'connectivity_test'}}}];
if (type === 'summary_report') return [{json:{http_status:200,manual_review:false,response:{ok:true,event_id:id,event_type:type,route:'summary_report',total_predictions:body.total_predictions,manual_review_count:body.manual_review_count}}}];
if (!Number.isInteger(body.predicted_class_id) || body.predicted_class_id < 0 || body.predicted_class_id > 55 || typeof body.model_probability !== 'number' || body.model_probability < 0 || body.model_probability > 1) return invalid('Invalid prediction metadata');
const flags = Array.isArray(body.triggered_workflows) ? body.triggered_workflows : [];
const review = (body.predicted_class_id === 55 && flags.includes('oos_routing')) || (body.is_low_confidence === true && flags.includes('low_confidence_review'));
const routes = flags.includes('intent_routing') && Array.isArray(body.matched_routes) ? body.matched_routes.filter(r=>typeof r==='string').slice(0,50) : [];
return [{json:{http_status:200,manual_review:review,response:{ok:true,event_id:id,event_type:type,route:review?'manual_review':routes.length?'class_specific':'metadata',predicted_class_id:body.predicted_class_id,model_probability:body.model_probability,matched_routes:routes,metadata_logging_requested:flags.includes('prediction_logging'),manual_review_required:review}}}];
